184	    private static void iteratedPreOrder() {
185	        if(topNode == null || topNode.getValue() == null) {
186	            System.out.println("空二叉树！请输入数据！");
187	            return;
188	        }
189	        Stack stack = new Stack();
190	        TreeNode node = topNode;
191	        while(node != null || !stack.isEmpty()) {
192	            while(node != null) {
193	                if(node.getValue() != null) {
194	                    System.out.print(node.getValue() + " ");
195	                }
196	                stack.push(node);
197	                node = node.getLeftNode();
198	            }
199	            if(!stack.isEmpty()) {
200	                node = stack.pop();
201	                node = node.getRightNode();
202	            }
203	        }
204	    }
