206	    private static void iteratedInOrder() {
207	        if(topNode == null || topNode.getValue() == null) {
208	            System.out.println("空二叉树！请输入数据！");
209	            return;
210	        }
211	        Stack stack = new Stack();
212	        TreeNode node = topNode;
213	        while(node != null || !stack.isEmpty()) {
214	            while(node != null) {
215	                stack.push(node);
216	                node = node.getLeftNode();
217	            }
218	            if(!stack.isEmpty()) {
219	                node = stack.pop();
220	                if(node.getValue() != null) {
221	                    System.out.print(node.getValue() + " ");
222	                }
223	                node = node.getRightNode();
224	            }
225	        }
226	    }
