228	    private static void iteratedPostOrder() {
229	        if(topNode == null || topNode.getValue() == null) {
230	            System.out.println("空二叉树！请输入数据！");
231	            return;
232	        }
233	        Stack stack = new Stack();
234	        TreeNode node = topNode;
235	        while(node != null || !stack.isEmpty()) {
236	            //一路向左，第一次经过的节点标记为1
237	            while(node != null) {
238	                node.setFlag(1);
239	                stack.push(node);
240	                node = node.getLeftNode();
241	            }
242	            //右子树已经访问过的节点可以出栈输出
243	            while(!stack.isEmpty() && stack.getTop().getFlag() == 2) {
244	                TreeNode tempNode = stack.pop();
245	                if(tempNode.getValue() != null) {
246	                    System.out.print(tempNode.getValue() + " ");
247	                }
248	            }
249	            //栈顶节点标记为2，转向它的右子树
250	            if(!stack.isEmpty()) {
251	                stack.getTop().setFlag(2);
252	                node = stack.getTop().getRightNode();
253	            }
254	        }
255	    }
