257	    private static void judgeTree() {
258	        if(topNode == null || topNode.getValue() == null) {
259	            System.out.println("空二叉树！请输入数据！");
260	            return;
261	        }
262	        Queue queue = new Queue();
263	        queue.enQueue(topNode);
264	        while(!queue.isEmpty()) {
265	            TreeNode tempNode = queue.getFirst();
266	            boolean hasLeft = tempNode.getLeftNode() != null && tempNode.getLeftNode().getValue() != null;
267	            boolean hasRight = tempNode.getRightNode() != null && tempNode.getRightNode().getValue() != null;
268	            if(hasLeft && hasRight) {
269	                //左右子树都存在，继续往下判断
270	                queue.deQueue();
271	                queue.enQueue(tempNode.getLeftNode());
272	                queue.enQueue(tempNode.getRightNode());
273	            }else if(!hasLeft && hasRight) {
274	                //只有右子树，一定不是完全二叉树
275	                System.out.println("该树不是完全二叉树！");
276	                return;
277	            }else {
278	                //没有右子树，后面的节点都必须是叶节点
279	                queue.deQueue();
280	                while(!queue.isEmpty()) {
281	                    tempNode = queue.getFirst();
282	                    if(tempNode.getLeftNode() != null && tempNode.getLeftNode().getValue() != null
283	                            || tempNode.getRightNode() != null && tempNode.getRightNode().getValue() != null) {
284	                        System.out.println("该树不是完全二叉树！");
285	                        return;
286	                    }
287	                    queue.deQueue();
288	                }
289	                System.out.println("该树是完全二叉树！");
290	                return;
291	            }
292	        }
293	        System.out.println("该树是完全二叉树！");
294	    }
