296	    private static void findAncestor() {
297	        System.out.println("请输入要查找祖先的两个节点的值（回车或空格间隔）：");
298	        String one = scanner.next();
299	        String another = scanner.next();
300	        TreeNode ancestorNode = findNearsetAncestor(topNode, one, another);
301	        System.out.println("两个节点最近的祖先节点的值是" + ancestorNode.getValue());
302	    }
303	
304	    private static TreeNode findNearsetAncestor(TreeNode root, String one, String another) {
305	        //如果当前节点为null说明走到了叶节点都没有找到两个节点中的其中一个
306	        //如果当前节点为p,q之中的一个，那么返回当前找到的节点中的一个
307	        if(root == null || root.getValue() == null || one.equals(root.getValue()) || another.equals(root.getValue())) {
308	            return root;
309	        }
310	        TreeNode leftNode = findNearsetAncestor(root.getLeftNode(), one, another);
311	        TreeNode rightNode = findNearsetAncestor(root.getRightNode(), one, another);
312	        //左右子树中各找到一个，那么当前节点就是最近的公共祖先
313	        if(leftNode != null && leftNode.getValue() != null && rightNode != null && rightNode.getValue() != null) {
314	            return root;
315	        }
316	        if(leftNode == null || leftNode.getValue() == null) {
317	            return rightNode;
318	        }
319	        return leftNode;
320	    }
321	}
