368	class Stack {
369	    private ArrayList<TreeNode> nodes = new ArrayList<>();
370	
371	    public void push(TreeNode node) {
372	        nodes.add(node);
373	    }
374	
375	    public TreeNode pop() {
376	        TreeNode tempNode = nodes.get(nodes.size() - 1);
377	        nodes.remove(nodes.size() - 1);
378	        return tempNode;
379	    }
380	
381	    public boolean isEmpty() {
382	        return nodes.isEmpty();
383	    }
384	
385	    public TreeNode getTop() {
386	        return nodes.get(nodes.size() - 1);
387	    }
388	}
