390	class Queue {
391	    private ArrayList<TreeNode> nodes = new ArrayList<>();
392	
393	    public void enQueue(TreeNode node) {
394	        nodes.add(node);
395	    }
396	
397	    public TreeNode deQueue() {
398	        return nodes.remove(0);
399	    }
400	
401	    public TreeNode getFirst() {
402	        return nodes.get(0);
403	    }
404	
405	    public boolean isEmpty() {
406	        return nodes.isEmpty();
407	    }
408	}

