import java.io.*;
import java.lang.reflect.*;
import java.net.*;
import java.util.*;

public class H {
    // ---- independent model ----
    static class N { int v; N l, r; N(int v){this.v=v;} }
    static int counter;
    // build all shapes of n nodes
    static List<N> shapes(int n){
        List<N> out = new ArrayList<>();
        if(n==0){ out.add(null); return out; }
        for(int i=0;i<n;i++){
            for(N L: shapes(i)) for(N R: shapes(n-1-i)){
                N root = new N(0); root.l=copy(L); root.r=copy(R); out.add(root);
            }
        }
        return out;
    }
    static N copy(N x){ if(x==null) return null; N y=new N(x.v); y.l=copy(x.l); y.r=copy(x.r); return y; }
    static void label(N x){ if(x==null) return; x.v=++counter; label(x.l); label(x.r); }
    static void pre(N x, StringBuilder sb){ if(x==null){ sb.append("# "); return;} sb.append(x.v).append(' '); pre(x.l,sb); pre(x.r,sb); }
    static void preList(N x, List<String> o){ if(x==null) return; o.add(""+x.v); preList(x.l,o); preList(x.r,o); }
    static void inList(N x, List<String> o){ if(x==null) return; inList(x.l,o); o.add(""+x.v); inList(x.r,o); }
    static void postList(N x, List<String> o){ if(x==null) return; postList(x.l,o); postList(x.r,o); o.add(""+x.v); }
    static List<String> levelList(N x){ List<String> o=new ArrayList<>(); Deque<N> q=new ArrayDeque<>(); if(x!=null)q.add(x);
        while(!q.isEmpty()){N c=q.poll(); o.add(""+c.v); if(c.l!=null)q.add(c.l); if(c.r!=null)q.add(c.r);} return o; }
    static boolean isComplete(N root){
        if(root==null) return true;
        Deque<N> q=new ArrayDeque<>(); q.add(root); boolean seenGap=false;
        while(!q.isEmpty()){ N c=q.poll();
            if(c==null){ seenGap=true; continue; }
            if(seenGap) return false;
            q.add(c.l); q.add(c.r);
        }
        return true;
    }
    static N lca(N r, int a, int b){
        if(r==null||r.v==a||r.v==b) return r;
        N L=lca(r.l,a,b), R=lca(r.r,a,b);
        if(L!=null&&R!=null) return r;
        return L!=null?L:R;
    }

    // ---- driver over a compiled build dir ----
    static class Impl {
        Class<?> c; Field scannerF, topF; Method inputTree, judgeTree, findAnc, outputTree;
        Impl(String dir) throws Exception {
            URLClassLoader cl = new URLClassLoader(new URL[]{ new File(dir).toURI().toURL() }, null);
            c = cl.loadClass("DSLab2");
            scannerF = c.getDeclaredField("scanner"); scannerF.setAccessible(true);
            topF = c.getDeclaredField("topNode"); topF.setAccessible(true);
            inputTree = c.getDeclaredMethod("inputTree"); inputTree.setAccessible(true);
            judgeTree = c.getDeclaredMethod("judgeTree"); judgeTree.setAccessible(true);
            findAnc = c.getDeclaredMethod("findAncestor"); findAnc.setAccessible(true);
            outputTree = c.getDeclaredMethod("outputTree"); outputTree.setAccessible(true);
        }
        void feed(String s) throws Exception {
            scannerF.set(null, new Scanner(new ByteArrayInputStream(s.getBytes("UTF-8"))));
        }
        String run(String stdin, Method m) throws Exception {
            PrintStream old = System.out;
            ByteArrayOutputStream bo = new ByteArrayOutputStream();
            System.setOut(new PrintStream(bo, true, "UTF-8"));
            try { m.invoke(null); }
            catch(InvocationTargetException e){ System.out.flush(); System.setOut(old);
                return bo.toString("UTF-8") + "\n<<EX:" + e.getCause().getClass().getName() + ">>"; }
            finally { System.out.flush(); System.setOut(old); }
            return bo.toString("UTF-8");
        }
        String build(String ser) throws Exception { feed(ser); return run(ser, inputTree); }
        String judge() throws Exception { return run("", judgeTree); }
        String anc(String a, String b) throws Exception { feed(a+" "+b+"\n"); return run("", findAnc); }
        String out(String choice) throws Exception { feed(choice); return run("", outputTree); }
        void reset() throws Exception { topF.set(null, null); }
    }

    public static void main(String[] a) throws Exception {
        Impl ref = new Impl("/tmp/adv02/ref");
        Impl neu = new Impl("/tmp/adv02/new");
        int cases=0, mismatch=0, judgeWrong=0, lcaWrong=0, travWrong=0;
        List<String> report = new ArrayList<>();
        for(int n=1;n<=7;n++){
            for(N sh : shapes(n)){
                counter=0; label(sh);
                StringBuilder sb=new StringBuilder(); pre(sh,sb);
                String ser = sb.toString().trim();
                // ---- judgeTree ----
                ref.reset(); neu.reset();
                ref.build(ser); neu.build(ser);
                String rj = ref.judge(), nj = neu.judge();
                cases++;
                if(!rj.equals(nj)){ mismatch++; if(report.size()<20) report.add("JUDGE DIFF ser="+ser+" ref="+rj.trim()+" new="+nj.trim()); }
                String expect = isComplete(sh) ? "该树是完全二叉树！" : "该树不是完全二叉树！";
                if(!nj.trim().equals(expect)){ judgeWrong++; if(judgeWrong<=6) report.add("JUDGE WRONG(vs model) ser="+ser+" got="+nj.trim()+" want="+expect+" refSame="+rj.equals(nj)); }
                // ---- traversals (all 6 + level) ----
                if(n<=6){
                    List<String> p=new ArrayList<>(), i=new ArrayList<>(), po=new ArrayList<>();
                    preList(sh,p); inList(sh,i); postList(sh,po);
                    String[][] modes = {{"1\n1\n",join(p)},{"1\n2\n",join(p)},{"2\n1\n",join(i)},{"2\n2\n",join(i)},{"3\n1\n",join(po)},{"3\n2\n",join(po)},{"4\n",join(levelList(sh))}};
                    for(String[] md: modes){
                        String ro=ref.out(md[0]), no=neu.out(md[0]);
                        if(!ro.equals(no)){ mismatch++; if(report.size()<20) report.add("TRAV DIFF ser="+ser+" mode="+md[0].replace("\n","/")+" ref="+ro+" new="+no); }
                        String got = no.substring(no.lastIndexOf("：")+1).trim();
                        if(!got.equals(md[1])){ travWrong++; if(travWrong<=6) report.add("TRAV WRONG ser="+ser+" mode="+md[0].replace("\n","/")+" got=["+got+"] want=["+md[1]+"]"); }
                    }
                }
                // ---- LCA over all ordered pairs incl. duplicates(u==v) ----
                if(n<=6){
                    for(int u=1;u<=n;u++) for(int v=1;v<=n;v++){
                        String ra=ref.anc(""+u,""+v), na=neu.anc(""+u,""+v);
                        if(!ra.equals(na)){ mismatch++; if(report.size()<20) report.add("LCA DIFF ser="+ser+" "+u+","+v+" ref="+ra+" new="+na); }
                        N m = lca(sh,u,v);
                        String want = "两个节点最近的祖先节点的值是"+(m==null?"null":m.v);
                        String got = na.trim();
                        if(!got.equals(want)){ lcaWrong++; if(lcaWrong<=6) report.add("LCA WRONG ser="+ser+" ("+u+","+v+") got="+got+" want="+want); }
                    }
                }
            }
        }
        System.out.println("trees exercised (n=1..7): "+cases);
        System.out.println("ref-vs-new DIFFERENCES : "+mismatch);
        System.out.println("judgeTree wrong vs model: "+judgeWrong);
        System.out.println("traversal wrong vs model: "+travWrong);
        System.out.println("LCA wrong vs model      : "+lcaWrong);
        for(String s: report) System.out.println("  "+s);
    }
    static String join(List<String> l){ return String.join(" ", l); }
}
