import java.io.*; import java.lang.reflect.*; import java.net.*; import java.util.*;
public class H2 {
    static class Impl {
        Class<?> c; Field sf, tf; Method in, jt, fa, ot;
        Impl(String d) throws Exception {
            URLClassLoader cl=new URLClassLoader(new URL[]{new File(d).toURI().toURL()},null);
            c=cl.loadClass("DSLab2");
            sf=c.getDeclaredField("scanner"); sf.setAccessible(true);
            tf=c.getDeclaredField("topNode"); tf.setAccessible(true);
            in=c.getDeclaredMethod("inputTree"); in.setAccessible(true);
            jt=c.getDeclaredMethod("judgeTree"); jt.setAccessible(true);
            fa=c.getDeclaredMethod("findAncestor"); fa.setAccessible(true);
            ot=c.getDeclaredMethod("outputTree"); ot.setAccessible(true);
        }
        void feed(String s) throws Exception { sf.set(null,new Scanner(new ByteArrayInputStream(s.getBytes("UTF-8")))); }
        String run(Method m) throws Exception {
            PrintStream o=System.out; ByteArrayOutputStream b=new ByteArrayOutputStream();
            System.setOut(new PrintStream(b,true,"UTF-8"));
            try{ m.invoke(null); }
            catch(InvocationTargetException e){ System.out.flush(); System.setOut(o); return b.toString("UTF-8")+"<<EX:"+e.getCause()+">>"; }
            finally{ System.out.flush(); System.setOut(o); }
            return b.toString("UTF-8");
        }
        String last(String s){ String[] p=s.trim().split("\n"); return p[p.length-1].trim(); }
    }
    static String[] TREES = {
        "7 3 1 # # 3 # # 7 # #",     // duplicates 7 and 3
        "a a a # # # a # #",          // all identical
        "1 1 # # 1 # #",
        "5 # # ",                     // single node
        "#",                          // empty
        "1 2 # 3 # # 4 # #",
        "1 2 3 # # # 4 # 5 # #",
    };
    static String[][] QUERIES = { {"7","7"},{"3","3"},{"1","3"},{"7","3"},{"a","a"},
        {"ZZ","QQ"},{"1","ZZ"},{"5","5"},{"5","nope"},{"#","#"},{"1","1"},{"4","5"},{"2","3"} };
    public static void main(String[] x) throws Exception {
        Impl r=new Impl("/tmp/adv02/ref"), n=new Impl("/tmp/adv02/new");
        int diffs=0, cases=0;
        for(String t: TREES){
            r.tf.set(null,null); n.tf.set(null,null);
            r.feed(t+" \n"); String rb=r.run(r.in);
            n.feed(t+" \n"); String nb=n.run(n.in);
            if(!rb.equals(nb)){ diffs++; System.out.println("BUILD DIFF "+t); }
            String rj=r.run(r.jt), nj=n.run(n.jt);
            cases++; if(!rj.equals(nj)){diffs++; System.out.println("JUDGE DIFF "+t);}
            System.out.println("tree=["+t+"]  judge -> "+r.last(rj));
            for(String[] q: QUERIES){
                r.feed(q[0]+" "+q[1]+"\n"); n.feed(q[0]+" "+q[1]+"\n");
                String ra=r.run(r.fa), na=n.run(n.fa);
                cases++;
                if(!ra.equals(na)){ diffs++; System.out.println("  LCA DIFF ("+q[0]+","+q[1]+") ref=["+r.last(ra)+"] new=["+n.last(na)+"]"); }
                System.out.println("    LCA("+q[0]+","+q[1]+") -> "+n.last(na));
            }
            // all traversals incl. repeated iterative post-order (flag state reuse)
            String[] modes={"1\n1\n","1\n2\n","2\n1\n","2\n2\n","3\n1\n","3\n2\n","3\n2\n","3\n2\n","4\n","5\n1\n","4\n"};
            for(String m: modes){
                r.feed(m); n.feed(m);
                String ro=r.run(r.ot), no=n.run(n.ot);
                cases++;
                if(!ro.equals(no)){ diffs++; System.out.println("  TRAV DIFF mode="+m.replace("\n","/")+" ref=["+r.last(ro)+"] new=["+n.last(no)+"]"); }
                System.out.println("    mode "+m.replace("\n","/")+" -> "+n.last(no));
            }
        }
        System.out.println("\ncases="+cases+"  ref-vs-new diffs="+diffs);
    }
}
